import{_ as e,o as s,c as t,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"项目四：待办事项管理小工具（综合实战）","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-5/project-4.md","filePath":"modules/module-5/project-4.md"}'),n={name:"modules/module-5/project-4.md"};function i(o,a,d,p,r,h){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="项目四-待办事项管理小工具-综合实战" tabindex="-1">项目四：待办事项管理小工具（综合实战） <a class="header-anchor" href="#项目四-待办事项管理小工具-综合实战" aria-label="Permalink to &quot;项目四：待办事项管理小工具（综合实战）&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：从零到一完成一个完整的 Web 应用开发<br> ⏱️ <strong>预计时长</strong>：30 分钟<br> 🎯 <strong>学到的能力</strong>：需求拆解、任务规划、全流程协作</p></blockquote><hr><h2 id="一、任务描述" tabindex="-1">一、任务描述 <a class="header-anchor" href="#一、任务描述" aria-label="Permalink to &quot;一、任务描述&quot;">​</a></h2><p>用 Codex 做一个&quot;待办事项管理&quot;小工具，具备以下功能：</p><ul><li>添加待办事项</li><li>标记已完成</li><li>删除事项</li><li>数据保存在本地浏览器中</li></ul><hr><h2 id="二、操作步骤" tabindex="-1">二、操作步骤 <a class="header-anchor" href="#二、操作步骤" aria-label="Permalink to &quot;二、操作步骤&quot;">​</a></h2><h3 id="步骤-1-用自然语言描述完整需求" tabindex="-1">步骤 1：用自然语言描述完整需求 <a class="header-anchor" href="#步骤-1-用自然语言描述完整需求" aria-label="Permalink to &quot;步骤 1：用自然语言描述完整需求&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个待办事项管理网页，功能要求：</span></span>
<span class="line"><span>1. 可以添加新的待办事项</span></span>
<span class="line"><span>2. 每个事项前面有复选框，点击可以标记为已完成</span></span>
<span class="line"><span>3. 已完成的事项显示为灰色并加删除线</span></span>
<span class="line"><span>4. 可以删除事项</span></span>
<span class="line"><span>5. 数据保存在浏览器的 localStorage 中，刷新页面不丢失</span></span>
<span class="line"><span>6. 界面简洁美观，支持深色模式切换</span></span></code></pre></div><h3 id="步骤-2-让-codex-拆解任务并制定计划" tabindex="-1">步骤 2：让 Codex 拆解任务并制定计划 <a class="header-anchor" href="#步骤-2-让-codex-拆解任务并制定计划" aria-label="Permalink to &quot;步骤 2：让 Codex 拆解任务并制定计划&quot;">​</a></h3><p>在 Codex 生成代码之前，让它先给出计划：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在开始写代码之前，请先告诉我你的实现计划，包括：</span></span>
<span class="line"><span>1. 使用什么技术栈</span></span>
<span class="line"><span>2. 文件结构是怎样的</span></span>
<span class="line"><span>3. 各个功能的实现思路</span></span></code></pre></div><h3 id="步骤-3-逐步实现" tabindex="-1">步骤 3：逐步实现 <a class="header-anchor" href="#步骤-3-逐步实现" aria-label="Permalink to &quot;步骤 3：逐步实现&quot;">​</a></h3><p>确认计划后，让 Codex 开始编码。Codex 会生成一个包含 HTML + CSS + JavaScript 的完整项目。</p><h3 id="步骤-4-测试与修正" tabindex="-1">步骤 4：测试与修正 <a class="header-anchor" href="#步骤-4-测试与修正" aria-label="Permalink to &quot;步骤 4：测试与修正&quot;">​</a></h3><p>将生成的代码保存为项目文件，在浏览器中打开测试：</p><ul><li>添加几个待办事项，检查是否能正常显示</li><li>点击复选框，检查是否能标记完成</li><li>删除一个事项，检查是否正确移除</li><li>刷新页面，检查数据是否保留</li></ul><p>如果发现问题，告诉 Codex：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我发现一个问题：删除事项后，计数没有更新。请修复这个问题。</span></span></code></pre></div><h3 id="步骤-5-验收成果" tabindex="-1">步骤 5：验收成果 <a class="header-anchor" href="#步骤-5-验收成果" aria-label="Permalink to &quot;步骤 5：验收成果&quot;">​</a></h3><p>功能全部正常后，你可以：</p><ul><li>添加更多功能（比如分类、优先级、搜索）</li><li>美化界面（添加动画、调整配色）</li><li>部署上线（部署到 GitHub Pages 或其他静态托管平台）</li></ul><hr><h2 id="三、进阶扩展" tabindex="-1">三、进阶扩展 <a class="header-anchor" href="#三、进阶扩展" aria-label="Permalink to &quot;三、进阶扩展&quot;">​</a></h2><h3 id="添加分类功能" tabindex="-1">添加分类功能 <a class="header-anchor" href="#添加分类功能" aria-label="Permalink to &quot;添加分类功能&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我给待办事项加上分类功能，可以按&quot;工作&quot;&quot;个人&quot;&quot;学习&quot;分类</span></span></code></pre></div><h3 id="添加提醒功能" tabindex="-1">添加提醒功能 <a class="header-anchor" href="#添加提醒功能" aria-label="Permalink to &quot;添加提醒功能&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我添加一个提醒功能，可以设置每个事项的截止日期</span></span></code></pre></div><h3 id="添加导出功能" tabindex="-1">添加导出功能 <a class="header-anchor" href="#添加导出功能" aria-label="Permalink to &quot;添加导出功能&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我添加一个导出功能，可以把待办事项导出为 JSON 或 CSV 文件</span></span></code></pre></div><hr><h2 id="四、本节实操任务清单" tabindex="-1">四、本节实操任务清单 <a class="header-anchor" href="#四、本节实操任务清单" aria-label="Permalink to &quot;四、本节实操任务清单&quot;">​</a></h2><p>请按顺序完成以下任务：</p><ul><li>[ ] 描述完整需求并让 Codex 制定计划</li><li>[ ] 确认计划后让 Codex 开始编码</li><li>[ ] 在浏览器中测试所有功能</li><li>[ ] 发现并修复至少一个问题</li><li>[ ] 尝试添加一个扩展功能</li></ul><hr><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>学到的能力</th><th>具体说明</th></tr></thead><tbody><tr><td>需求拆解</td><td>将复杂需求拆分成可执行的任务</td></tr><tr><td>任务规划</td><td>让 Codex 先给出实现计划</td></tr><tr><td>全流程协作</td><td>从需求到交付的完整开发流程</td></tr><tr><td>测试验证</td><td>发现问题并及时反馈修正</td></tr></tbody></table><hr><h2 id="六、下一步" tabindex="-1">六、下一步 <a class="header-anchor" href="#六、下一步" aria-label="Permalink to &quot;六、下一步&quot;">​</a></h2><p><a href="./../module-6/lesson-15.html">→ 进入模块六：总结与进阶</a></p>`,41)])])}const b=e(n,[["render",i]]);export{u as __pageData,b as default};
